css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); border-radius: 22%; background: color-mix(in srgb, var(--accent) 12%, transparent); border: calc(var(--loader-size) * .035) solid color-mix(in srgb, var(--accent) 45%, transparent); position: relative; overflow: hidden; box-sizing: border-box; }
.loader span { position: absolute; left: 0; right: 0; bottom: 0; height: 40%; background: linear-gradient(var(--accent-2), var(--accent)); animation: rise calc(var(--loader-speed) * 3.4) ease-in-out infinite alternate; }
.loader span::before, .loader span::after { content: ''; position: absolute; bottom: 96%; left: -50%; width: 200%; height: calc(var(--loader-size) * .16); background: inherit; border-radius: 45%; }
.loader span::before { animation: surface calc(var(--loader-speed) * 1.6) linear infinite; opacity: .85; }
.loader span::after { animation: surface calc(var(--loader-speed) * 2.4) linear infinite reverse; }
@keyframes rise { 0% { height: 28%; } 100% { height: 80%; } }
@keyframes surface { 0% { transform: translateX(0); } 100% { transform: translateX(25%); } }
